package com.company.skillplatform.bundle.application;
import com.company.skillplatform.artifact.infrastructure.entity.SkillArtifactEntity;import com.company.skillplatform.artifact.infrastructure.repository.SkillArtifactRepository;import com.company.skillplatform.bundle.infrastructure.entity.*;import com.company.skillplatform.bundle.infrastructure.repository.*;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.common.logging.LogContext;import com.company.skillplatform.compatibility.infrastructure.entity.PlatformEntity;import com.company.skillplatform.compatibility.infrastructure.repository.PlatformRepository;import com.company.skillplatform.dependency.application.DependencyService;import com.company.skillplatform.storage.domain.ObjectStoragePort;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import com.company.skillplatform.version.domain.LifecycleStatus;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.version.infrastructure.repository.SkillVersionRepository;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import java.util.zip.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BundleService{
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(BundleService.class);
 private static final int MAX_ROOTS=50;private final SkillBundleRepository bundles;private final SkillBundleItemRepository items;private final SkillBundleFailureRepository failures;private final PlatformRepository platforms;private final IamUserRepository users;private final SkillVersionRepository versions;private final DependencyService deps;private final SkillArtifactRepository artifacts;private final ObjectStoragePort storage;public BundleService(SkillBundleRepository b,SkillBundleItemRepository i,SkillBundleFailureRepository f,PlatformRepository p,IamUserRepository u,SkillVersionRepository v,DependencyService d,SkillArtifactRepository a,ObjectStoragePort s){bundles=b;items=i;failures=f;platforms=p;users=u;versions=v;deps=d;artifacts=a;storage=s;}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional public BundleView create(CreateCommand c,Long actorId){long t0=System.nanoTime();validate(c);String platformKey=c.platform().toUpperCase(Locale.ROOT),requestedOs=c.osType().toUpperCase(Locale.ROOT);PlatformEntity platform=platforms.findByPlatformKey(platformKey).filter(p->"ACTIVE".equals(p.getStatus())).orElseThrow(()->{log.warn("event=bundle.create.failed requestId={} actorId={} platform={} osType={} errorCode={}",LogContext.requestId(),actorId,platformKey,requestedOs,"PLATFORM_NOT_AVAILABLE");return error("PLATFORM_NOT_AVAILABLE","Platform does not exist or is disabled",HttpStatus.UNPROCESSABLE_ENTITY);});LinkedHashMap<Long,Selection> selected=new LinkedHashMap<>();for(Long rootId:c.rootVersionIds()){SkillVersionEntity root=published(rootId);merge(selected,root,0,root.getSkill().getSkillKey(),true);if(c.includeDependencies()){DependencyService.ResolveView resolved=deps.resolve(rootId);if(!resolved.conflicts().isEmpty()){log.warn("event=bundle.create.failed requestId={} actorId={} platform={} osType={} errorCode={} conflicts={}",LogContext.requestId(),actorId,platformKey,requestedOs,"BUNDLE_DEPENDENCY_CONFLICT",resolved.conflicts().size());throw error("BUNDLE_DEPENDENCY_CONFLICT",String.join("; ",resolved.conflicts()),HttpStatus.UNPROCESSABLE_ENTITY);}for(var resolvedItem:resolved.items()){SkillVersionEntity dependency=versions.findAll().stream().filter(v->resolvedItem.skillKey().equals(v.getSkill().getSkillKey())&&resolvedItem.version().equals(v.getVersion())).findFirst().orElseThrow(()->{log.warn("event=bundle.create.failed requestId={} actorId={} platform={} osType={} errorCode={} skillKey={} resolvedVersion={}",LogContext.requestId(),actorId,platformKey,requestedOs,"BUNDLE_RESOLVED_VERSION_NOT_FOUND",resolvedItem.skillKey(),resolvedItem.version());return error("BUNDLE_RESOLVED_VERSION_NOT_FOUND","Resolved dependency not found: "+resolvedItem.skillKey(),HttpStatus.UNPROCESSABLE_ENTITY);});merge(selected,dependency,resolvedItem.depth(),resolvedItem.requiredByPath(),false);}}}String lock=hash(selected.keySet().toString()+platformKey+requestedOs);String key=hash(actorId+"|"+lock+"|bundle-v2");var old=bundles.findByBundleKey(key);if(old.isPresent()){log.info("event=bundle.cache.hit requestId={} actorId={} platform={} osType={} bundleId={} bundleKey={} lockHash={}",LogContext.requestId(),actorId,platformKey,requestedOs,old.get().getId(),key,lock);return view(old.get(),items.findByBundleId(old.get().getId()));}SkillBundleEntity bundle=bundles.save(new SkillBundleEntity(key,platform,requestedOs,c.includeDependencies(),lock,users.findById(actorId).orElseThrow()));LogContext.putTask(String.valueOf(bundle.getId()),1);try{ByteArrayOutputStream output=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(output)){for(Selection selection:selected.values()){SkillArtifactEntity artifact=artifact(selection.version(),platformKey,requestedOs);zip.putNextEntry(new ZipEntry(selection.version().getSkill().getSkillKey()+"/"+artifact.getFileName()));try(InputStream input=storage.get(artifact.getObjectKey())){input.transferTo(zip);}zip.closeEntry();items.save(new SkillBundleItemEntity(bundle,selection.version(),artifact,selection.root(),selection.depth(),String.join(" | ",selection.paths())));}}byte[] bytes=output.toByteArray();String object="bundles/"+key+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");bundle.available(object,bytes.length,hashBytes(bytes));bundles.save(bundle);log.info("event=bundle.build.succeeded requestId={} actorId={} platform={} osType={} bundleId={} bundleKey={} lockHash={} itemCount={} sizeBytes={} durationMs={}",LogContext.requestId(),actorId,platformKey,requestedOs,bundle.getId(),key,lock,selected.size(),bytes.length,elapsed(t0));return view(bundle,items.findByBundleId(bundle.getId()));}catch(IOException ex){log.error("event=bundle.build.failed requestId={} actorId={} platform={} osType={} bundleId={} bundleKey={} errorCode={}",LogContext.requestId(),actorId,platformKey,requestedOs,bundle.getId(),key,"BUNDLE_BUILD_FAILED",ex);throw error("BUNDLE_BUILD_FAILED","Unable to build bundle",HttpStatus.UNPROCESSABLE_ENTITY);}finally{LogContext.clearTask();}}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional public BundleView createAgentBundle(List<SkillVersionEntity> roots,String platformKey,String requestedOs,Long actorId){String targetPlatform=platformKey.toUpperCase(Locale.ROOT),targetOs=requestedOs.toUpperCase(Locale.ROOT);PlatformEntity platform=platforms.findByPlatformKey(targetPlatform).filter(p->"ACTIVE".equals(p.getStatus())).orElseThrow(()->error("PLATFORM_NOT_AVAILABLE","Platform does not exist or is disabled",HttpStatus.UNPROCESSABLE_ENTITY));String key=hash(actorId+"|agent|"+roots.stream().map(v->v.getId()).sorted().toList()+"|"+targetPlatform+"|"+targetOs);var cached=bundles.findByBundleKey(key);if(cached.isPresent())return view(cached.get(),items.findByBundleId(cached.get().getId()));SkillBundleEntity bundle=bundles.save(new SkillBundleEntity(key,platform,targetOs,true,hash(key),users.findById(actorId).orElseThrow()));Map<Long,Selection> selected=new LinkedHashMap<>();Map<Long,SkillArtifactEntity> selectedArtifacts=new LinkedHashMap<>();List<FailureView> failedRoots=new ArrayList<>();for(SkillVersionEntity root:roots){try{Map<Long,Selection> rootSelected=new LinkedHashMap<>();merge(rootSelected,root,0,root.getSkill().getSkillKey(),true);DependencyService.ResolveView resolved=deps.resolve(root.getId());if(!resolved.conflicts().isEmpty())throw new BundleItemException("BUNDLE_DEPENDENCY_CONFLICT","依赖存在冲突");for(var ref:resolved.items()){SkillVersionEntity dependency=versions.findAll().stream().filter(v->ref.skillKey().equals(v.getSkill().getSkillKey())&&ref.version().equals(v.getVersion())).findFirst().orElseThrow(()->new BundleItemException("BUNDLE_RESOLVED_VERSION_NOT_FOUND","依赖版本不存在"));merge(rootSelected,dependency,ref.depth(),ref.requiredByPath(),false);}Map<Long,SkillArtifactEntity> rootArtifacts=new LinkedHashMap<>();for(Selection selection:rootSelected.values())rootArtifacts.put(selection.version().getId(),artifact(selection.version(),targetPlatform,targetOs));selected.putAll(rootSelected);selectedArtifacts.putAll(rootArtifacts);}catch(Exception ex){String code=ex instanceof BundleItemException b?b.code():"BUNDLE_ARTIFACT_NOT_FOUND";String message=ex instanceof BundleItemException b?b.getMessage():"该 Skill 不满足当前平台或操作系统";failedRoots.add(new FailureView(root.getSkill().getSkillKey(),root.getSkill().getDisplayName(),code,message));}}
        for(FailureView failure:failedRoots)failures.save(new SkillBundleFailureEntity(bundle,failure.skillKey(),failure.displayName(),failure.errorCode(),failure.message()));
        if(selected.isEmpty()){bundle.unavailable("NO_COMPATIBLE_ITEMS","没有可用于当前平台和操作系统的 Skill");bundles.save(bundle);return view(bundle,List.of());}
        try{ByteArrayOutputStream output=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(output)){for(Selection selection:selected.values()){SkillArtifactEntity a=selectedArtifacts.get(selection.version().getId());zip.putNextEntry(new ZipEntry(selection.version().getSkill().getSkillKey()+"/"+a.getFileName()));try(InputStream input=storage.get(a.getObjectKey())){input.transferTo(zip);}zip.closeEntry();items.save(new SkillBundleItemEntity(bundle,selection.version(),a,selection.root(),selection.depth(),String.join(" | ",selection.paths())));}}byte[] bytes=output.toByteArray();String object="bundles/"+key+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");bundle.available(object,bytes.length,hashBytes(bytes));bundles.save(bundle);return view(bundle,items.findByBundleId(bundle.getId()));}catch(IOException ex){bundle.failed("BUNDLE_BUILD_FAILED","无法生成批量下载包");bundles.save(bundle);throw error("BUNDLE_BUILD_FAILED","Unable to build bundle",HttpStatus.UNPROCESSABLE_ENTITY);}}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public Page<BundleView> list(Long actorId,Pageable pageable){return bundles.findByCreatedById(actorId,pageable).map(b->view(b,items.findByBundleId(b.getId())));}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public BundleView get(Long id,Long actorId){SkillBundleEntity b=owned(id,actorId);return view(b,items.findByBundleId(id));}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public List<BundleItemView> items(Long id,Long actorId){owned(id,actorId);return items.findByBundleId(id).stream().map(this::itemView).toList();}
 @Transactional public void retryBuild(Long id){SkillBundleEntity b=bundles.findById(id).orElseThrow(()->error("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND));LogContext.putTask(String.valueOf(b.getId()),b.getRetryCount()+1);log.info("event=bundle.build.retry requestId={} bundleId={} bundleKey={} attempt={} platform={} osType={}",LogContext.requestId(),b.getId(),b.getBundleKey(),b.getRetryCount()+1,b.getPlatform().getPlatformKey(),b.getOsType());try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(SkillBundleItemEntity item:items.findByBundleId(id)){SkillArtifactEntity a=item.getArtifact();zip.putNextEntry(new ZipEntry(item.getVersion().getSkill().getSkillKey()+"/"+a.getFileName()));try(InputStream in=storage.get(a.getObjectKey())){in.transferTo(zip);}zip.closeEntry();}}byte[] bytes=out.toByteArray();String object="bundles/"+b.getBundleKey()+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");b.available(object,bytes.length,hashBytes(bytes));bundles.save(b);log.info("event=bundle.build.retry_succeeded requestId={} bundleId={} bundleKey={} attempt={} sizeBytes={}",LogContext.requestId(),b.getId(),b.getBundleKey(),b.getRetryCount(),bytes.length);}catch(Exception ex){String message=ex.getMessage()==null?"Bundle retry failed":ex.getMessage();b.failed("BUNDLE_RETRY_FAILED",message.substring(0,Math.min(1024,message.length())));bundles.save(b);log.error("event=bundle.build.retry_failed requestId={} bundleId={} bundleKey={} attempt={} errorCode={}",LogContext.requestId(),b.getId(),b.getBundleKey(),b.getRetryCount(),"BUNDLE_RETRY_FAILED",ex);}finally{LogContext.clearTask();}}
 private void validate(CreateCommand c){if(c.rootVersionIds()==null||c.rootVersionIds().isEmpty())throw error("BUNDLE_ROOTS_REQUIRED","At least one root version is required",HttpStatus.BAD_REQUEST);if(c.rootVersionIds().size()>MAX_ROOTS)throw error("BUNDLE_ROOT_LIMIT_EXCEEDED","At most 50 root versions are allowed",HttpStatus.BAD_REQUEST);if(new HashSet<>(c.rootVersionIds()).size()!=c.rootVersionIds().size())throw error("BUNDLE_DUPLICATE_ROOT","Root version IDs must be unique",HttpStatus.BAD_REQUEST);}
 private void merge(Map<Long,Selection> selected,SkillVersionEntity version,int depth,String path,boolean root){Selection old=selected.get(version.getId());if(old==null){LinkedHashSet<String> paths=new LinkedHashSet<>();paths.add(path);selected.put(version.getId(),new Selection(version,depth,paths,root));}else{old.paths().add(path);selected.put(version.getId(),new Selection(version,Math.min(old.depth(),depth),old.paths(),old.root()||root));}}
 private SkillArtifactEntity artifact(SkillVersionEntity version,String platform,String requestedOs){return artifacts.findFirstByVersionIdAndPlatformPlatformKeyAndOsTypeAndStatus(version.getId(),platform,requestedOs,"AVAILABLE").or(()->"ANY".equals(requestedOs)?Optional.empty():artifacts.findFirstByVersionIdAndPlatformPlatformKeyAndOsTypeAndStatus(version.getId(),platform,"ANY","AVAILABLE")).orElseThrow(()->error("BUNDLE_ARTIFACT_NOT_FOUND","Artifact missing for skill="+version.getSkill().getSkillKey()+", platform="+platform+", osType="+requestedOs,HttpStatus.UNPROCESSABLE_ENTITY));}
 private SkillBundleEntity owned(Long id,Long actorId){return bundles.findByIdAndCreatedById(id,actorId).orElseThrow(()->error("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND));}private SkillVersionEntity published(Long id){SkillVersionEntity v=versions.findById(id).orElseThrow(()->error("SKILL_VERSION_NOT_FOUND","Skill version not found",HttpStatus.NOT_FOUND));if(v.getVersion()==null||!(v.getLifecycleStatus()==LifecycleStatus.PUBLISHED||v.getLifecycleStatus()==LifecycleStatus.DEPRECATED))throw error("BUNDLE_VERSION_NOT_DOWNLOADABLE","Root version is not published or deprecated",HttpStatus.UNPROCESSABLE_ENTITY);return v;}private String hash(String s){return hashBytes(s.getBytes(StandardCharsets.UTF_8));}private String hashBytes(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}private BusinessException error(String code,String message,HttpStatus status){return new BusinessException(code,message,status);}private BundleItemView itemView(SkillBundleItemEntity i){return new BundleItemView(i.getVersion().getSkill().getSkillKey(),i.getVersion().getId(),i.getVersion().getVersion(),i.isRootSelected(),i.getDependencyDepth(),List.of(i.getRequiredByPath().split(" \\| ")),i.getArtifact().getId(),i.getArtifact().getOsType(),i.getArtifact().getFileName(),i.getArtifact().getSha256());}private BundleView view(SkillBundleEntity b,List<SkillBundleItemEntity> rows){List<FailureView> failed=failures.findByBundleId(b.getId()).stream().map(f->new FailureView(f.getSkillKey(),f.getDisplayName(),f.getErrorCode(),f.getErrorMessage())).toList();String result=failed.isEmpty()?"COMPLETE":rows.isEmpty()?"FAILED":"PARTIAL";return new BundleView(b.getId(),b.getBundleKey(),b.getStatus(),b.getPlatform().getPlatformKey(),b.getOsType(),b.isIncludeDependencies(),b.getFileName(),b.getSizeBytes(),b.getSha256(),b.getErrorCode(),b.getErrorMessage(),b.getTimeCreated(),rows.stream().map(this::itemView).toList(),failed,result);}
 private record Selection(SkillVersionEntity version,int depth,LinkedHashSet<String> paths,boolean root){}private static final class BundleItemException extends RuntimeException{private final String code;private BundleItemException(String code,String message){super(message);this.code=code;}String code(){return code;}}private long elapsed(long startNanos){return (System.nanoTime()-startNanos)/1_000_000L;}public record CreateCommand(String platform,String osType,List<Long> rootVersionIds,boolean includeDependencies){}public record BundleItemView(String skillKey,Long versionId,String version,boolean root,int depth,List<String> requiredByPaths,Long artifactId,String artifactOsType,String artifactFileName,String artifactSha256){}public record FailureView(String skillKey,String displayName,String errorCode,String message){}public record BundleView(Long id,String bundleKey,String status,String platform,String osType,boolean includeDependencies,String fileName,Long sizeBytes,String sha256,String errorCode,String errorMessage,Instant createdAt,List<BundleItemView> items,List<FailureView> failures,String resultStatus){}
}
